import{c as o,Z as e,Q as i,j as l,m as r,o as s}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"蟾宫曲·春情","description":"","frontmatter":{"title":"蟾宫曲·春情","author":"徐再思","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/8.md","filePath":"books/shici/yuanqu/8.md"}'),n={name:"books/shici/yuanqu/8.md"};function u(h,a,p,c,d,q){const t=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="蟾宫曲·春情" tabindex="-1">蟾宫曲·春情 <a class="header-anchor" href="#蟾宫曲·春情" aria-label="Permalink to &quot;蟾宫曲·春情&quot;">​</a></h1><p><strong>[元] <a href="/authors/xuzaisi.html">徐再思</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>平生不会相思，才会相思，便害相思。身似浮云，心如飞絮，气若游丝。</p><p>空一缕余香在此，盼千金游子何之。证候来时，正是何时？灯半昏时，月半明时。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>蟾宫曲：曲牌名，又名&quot;折桂令&quot;</li><li>春情：春日里的情思</li><li>害相思：因相思而生病</li><li>身似浮云：身体像浮云一样飘忽不定</li><li>心如飞絮：心像柳絮一样纷乱</li><li>气若游丝：气息像游丝一样微弱</li><li>余香：残留的香气</li><li>千金游子：贵重的游子，指思念的人</li><li>何之：去了哪里</li><li>证候：症状</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>平生从来不懂相思，刚刚懂得相思，便害了相思之病。身体像浮云一样飘忽，心像飞絮一样纷乱，气息像游丝一样微弱。</p><p>空留一缕余香在这里，盼望那远行的游子去了何方。相思的症状来临时，是什么时候呢？正是灯光半昏半暗时，月色半明半亮时。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令是徐再思的代表作，以细腻的笔触描写了少女初识相思的情态，是元曲中描写闺情的佳作。</p><p>&quot;平生不会相思，才会相思，便害相思&quot;，开篇连用三个&quot;相思&quot;，层层递进，写出了少女从不懂相思到深陷相思的过程。语言朴素直白，却将少女的情窦初开表现得真切动人。</p><p>&quot;身似浮云，心如飞絮，气若游丝&quot;，以三个比喻写相思之状。身体飘忽如浮云，心绪纷乱如飞絮，气息微弱如游丝，将相思之苦形象地描绘出来。</p><p>&quot;空一缕余香在此，盼千金游子何之&quot;，写少女空闺独守，盼望游子归来的心情。&quot;余香&quot;既是实写，也是虚写，暗示了游子的离去和少女的思念。</p><p>&quot;证候来时，正是何时？灯半昏时，月半明时&quot;，以问句出之，写出了相思最难熬的时刻。灯光半昏、月色半明之时，正是夜深人静、思念最切之际。</p><p>全曲语言清新，情感真挚，将少女初识相思的情态描绘得细腻动人。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>徐再思</strong>（约1280年－1330年后），字德可，号甜斋，元代散曲家。其散曲多写闺情和闲适生活，风格清丽婉约。</p><p><a href="/authors/xuzaisi.html">查看作者详情 →</a></p></blockquote>',20)),s(t)])}const b=o(n,[["render",u]]);export{m as __pageData,b as default};
